insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('anchors-in-the-room-orienting-card', 'Anchors in the Room Orienting Card', 'worksheet'::resource_kind, 'A card listing five things in the room a client can name to remind their body where and when they are.', 'Use it to help a client orient to the present when reminders pull them back.', array['Adults']::text[], '15 minutes', 'Build the card in session with the client choosing the anchors. Practice once while calm so it is familiar. Keep it to the here and now; the card never asks the client to describe what happened. Pace the practice to what feels manageable today.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see right now:"}, {"id": "f1", "type": "textarea", "label": "Two sounds I can hear in this room:"}, {"id": "f2", "type": "textarea", "label": "Today''s date and where I am:"}, {"id": "f3", "type": "textarea", "label": "One sentence to tell myself that is true today:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'orienting']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-five-senses-kit-plan', 'Self-Soothe With Five Senses Kit Plan', 'dbt'::resource_kind, 'A plan for packing a small kit that soothes through sight, sound, smell, taste and touch.', 'Use it to help a client settle a stirred-up body using comforting things they pick.', array['Adults', 'Teens']::text[], '25 minutes', 'Let the client choose each item, since what soothes varies by person. Rehearse using one item in session and note any item that brings up an unwanted reminder, then swap it out. This is about stabilizing and comfort, not processing.', '[{"id": "f0", "type": "textarea", "label": "Something comforting to look at:"}, {"id": "f1", "type": "textarea", "label": "A sound or song that calms me:"}, {"id": "f2", "type": "textarea", "label": "A scent I find soothing:"}, {"id": "f3", "type": "textarea", "label": "A taste or texture that helps:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my kit:"}]'::jsonb, array['PTSD and trauma', 'self-soothe', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('values-compass-for-moving-forward-page', 'Values Compass for Moving Forward Page', 'act'::resource_kind, 'A page for naming what matters to a client and one small step toward it while reminders are still around.', 'Use it to help a client take values-led steps at a pace that feels safe.', array['Adults']::text[], '30 minutes', 'Keep the focus on what the client wants their life to include, not on the past. Choose a step small enough that they could do it on a hard day. Revisit pacing each time and let the client slow down whenever they need to.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me in my relationships:"}, {"id": "f1", "type": "textarea", "label": "What I would like more of in my days:"}, {"id": "f2", "type": "textarea", "label": "A small step I could take this week:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way, and what helps:"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('stuck-thought-gentle-check-in-sheet', 'Stuck Thought Gentle Check-In Sheet', 'cbt'::resource_kind, 'A sheet for noticing one unhelpful thought about safety or blame and writing a kinder, more balanced one.', 'Use it to help a client loosen a stuck thought about the present without retelling events.', array['Adults']::text[], '20 minutes', 'Work only with a thought as it shows up today, such as ''I am never safe'', and leave out the details of the event. Offer two or three alternatives and let the client pick the wording that rings true. Stop if the exercise stirs up more than they can handle.', '[{"id": "f0", "type": "textarea", "label": "The thought that showed up:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believed it, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "What I know about today that fits or does not fit it:"}, {"id": "f3", "type": "textarea", "label": "A more balanced way to say it:"}]'::jsonb, array['PTSD and trauma', 'balanced thinking', 'thought record']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('steady-objects-room-hunt', 'Steady Objects Room Hunt', 'game'::resource_kind, 'A group game where players find objects in the room that feel steady, calm or safe.', 'Use it to help a group practice noticing safety cues in their surroundings.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player gets three turns to find and name an object that feels steady and say why. Rules: no one has to share what they do not want to, and anyone may pass or sit out. Debrief on what it was like to look for safety in the room.', '[{"id": "f0", "type": "textarea", "label": "The object I picked and why it feels steady:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body as I looked:"}, {"id": "f2", "type": "textarea", "label": "An object another player picked that I liked:"}, {"id": "f3", "type": "textarea", "label": "One safety cue I can carry with me:"}]'::jsonb, array['PTSD and trauma', 'game', 'grounding']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('worry-time-window-and-parking-lot', 'Worry Time Window and Parking Lot', 'worksheet'::resource_kind, 'A worksheet for setting a daily worry window and jotting worries in a parking lot until then.', 'Use it to help a client contain worry to a set time instead of all day.', array['Adults', 'Teens']::text[], 'One week', 'Agree on a 15 minute window that is not near bedtime. Between windows the client writes the worry down briefly and returns to the task. At the window they decide which worries have a next step. Expect it to feel odd for a few days.', '[{"id": "f0", "type": "textarea", "label": "My worry window time:"}, {"id": "f1", "type": "textarea", "label": "Worries I parked today:"}, {"id": "f2", "type": "textarea", "label": "Which ones have a step I can take:"}, {"id": "f3", "type": "textarea", "label": "What I did when a worry popped up outside the window:"}]'::jsonb, array['anxiety', 'worry', 'containment']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('fear-forecast-versus-reality-tracker', 'Fear Forecast Versus Reality Tracker', 'cbt'::resource_kind, 'A tracker pairing a client''s anxious prediction with what actually happened.', 'Use it to help a client compare what they feared with what occurred.', array['Adults', 'Teens']::text[], 'Two weeks', 'Have the client record the prediction and a rating before the event, then the outcome and a rating after. Review a week of entries together and look for patterns in how accurate the predictions were, without pushing a conclusion.', '[{"id": "f0", "type": "textarea", "label": "What I predicted would happen:"}, {"id": "f1", "type": "textarea", "label": "How sure I was, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I notice when I compare the two:"}]'::jsonb, array['anxiety', 'behavioral experiment', 'predictions']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('anxiety-as-passenger-bus-metaphor-page', 'Anxiety as Passenger Bus Metaphor Page', 'act'::resource_kind, 'A page using the passengers-on-the-bus image to practice carrying anxiety while driving toward what matters.', 'Use it to help a client act on values with anxiety riding along.', array['Adults']::text[], '25 minutes', 'Draw the bus together with anxiety as a loud passenger. Ask where the client wants to drive and what the passenger says to stop them. The aim is not to silence the passenger but to keep driving. Let the client add other passengers.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive my bus:"}, {"id": "f1", "type": "textarea", "label": "What my anxious passenger shouts:"}, {"id": "f2", "type": "textarea", "label": "What I do when it gets loud:"}, {"id": "f3", "type": "textarea", "label": "One turn toward my values I will make this week:"}]'::jsonb, array['anxiety', 'ACT', 'values', 'metaphor']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('worry-eater-mailbox-craft', 'Worry Eater Mailbox Craft', 'kids'::resource_kind, 'A craft where a child decorates a box and feeds it folded worry notes at a set time.', 'Use it to help a child hand worries to a place outside their head.', array['Children']::text[], '30 minutes', 'The child decorates a box with a face and cuts a mouth. Each day at a set time the child, with a parent, drops in a drawn or dictated worry. The parent stays calm, listens briefly and avoids solving every worry. Review what feels lighter.', '[{"id": "f0", "type": "textarea", "label": "A name for my worry monster:"}, {"id": "f1", "type": "textarea", "label": "A worry I fed it today:"}, {"id": "f2", "type": "textarea", "label": "How my body felt after:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said that helped:"}]'::jsonb, array['anxiety', 'children', 'craft', 'worry']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('calm-down-dice-breathing-game', 'Calm Down Dice Breathing Game', 'game'::resource_kind, 'A dice game where each roll picks a calming action for the player to try.', 'Use it to help players practice a menu of calming skills in a light way.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Make a table of six calming actions such as slow breaths, stretching and counting. Players roll, do the action, and rate their calm before and after. Rules: take turns, no wrong answers, pass is allowed. Debrief which actions suited them.', '[{"id": "f0", "type": "textarea", "label": "The action I rolled:"}, {"id": "f1", "type": "textarea", "label": "My calm rating before and after:"}, {"id": "f2", "type": "textarea", "label": "The action I liked best:"}, {"id": "f3", "type": "textarea", "label": "When I could use it this week:"}]'::jsonb, array['anxiety', 'game', 'calming skills']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('low-mood-energy-budget-planner', 'Low Mood Energy Budget Planner', 'worksheet'::resource_kind, 'A planner for spending a limited amount of energy across must-do, meaningful and restful activities.', 'Use it to help a client plan a day around the energy they actually have.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to rate energy each morning and pick one task from each column. Treat a missed plan as information, not failure. Keep the list small and revisit it weekly with the client.', '[{"id": "f0", "type": "textarea", "label": "My energy this morning, zero to ten:"}, {"id": "f1", "type": "textarea", "label": "One must-do for today:"}, {"id": "f2", "type": "textarea", "label": "One thing that matters to me:"}, {"id": "f3", "type": "textarea", "label": "One restful thing I will let count:"}]'::jsonb, array['depression', 'energy', 'planning']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('small-win-evidence-log', 'Small Win Evidence Log', 'cbt'::resource_kind, 'A log for writing down one small thing done each day and what it says about the client.', 'Use it to help a client notice effort that low mood tends to erase.', array['Adults', 'Teens']::text[], 'Two weeks', 'Have the client log one thing daily, however small. At review, read entries back and ask what they notice about the days that held more. Avoid arguing with the client''s mood; let the entries do the work.', '[{"id": "f0", "type": "textarea", "label": "What I did today:"}, {"id": "f1", "type": "textarea", "label": "How hard it felt, zero to ten:"}, {"id": "f2", "type": "textarea", "label": "What the harsh voice said about it:"}, {"id": "f3", "type": "textarea", "label": "What the entry shows instead:"}]'::jsonb, array['depression', 'behavioral activation', 'self-talk']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('tiny-values-action-ladder', 'Tiny Values Action Ladder', 'act'::resource_kind, 'A ladder of five steps from smallest to largest toward something the client values.', 'Use it to help a client move toward a value when motivation is low.', array['Adults']::text[], '25 minutes', 'Start with the value, then build five rungs so the bottom rung takes under two minutes. Encourage acting before the mood shifts. Check in on the first rung each session and celebrate that it happened.', '[{"id": "f0", "type": "textarea", "label": "A value I would like to live by:"}, {"id": "f1", "type": "textarea", "label": "The two-minute first rung:"}, {"id": "f2", "type": "textarea", "label": "The next rung up:"}, {"id": "f3", "type": "textarea", "label": "The top rung, someday:"}]'::jsonb, array['depression', 'values', 'small steps']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-heavy-days-card', 'Opposite Action for Heavy Days Card', 'dbt'::resource_kind, 'A card for noticing the urge to withdraw and trying the opposite action in a small way.', 'Use it to help a client test acting against a low-mood urge.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the urge, such as staying in bed or canceling plans, and pick one small opposite action together. Check that the action is safe and doable. Review how the body and mood responded afterward and adjust the size of the next step.', '[{"id": "f0", "type": "textarea", "label": "The urge my mood is giving me:"}, {"id": "f1", "type": "textarea", "label": "The small opposite action I choose:"}, {"id": "f2", "type": "textarea", "label": "What I felt before and after:"}, {"id": "f3", "type": "textarea", "label": "What I would try next time:"}]'::jsonb, array['depression', 'opposite action', 'emotion regulation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('partner-support-menu-for-low-days', 'Partner Support Menu for Low Days', 'couples'::resource_kind, 'A menu where each partner lists the support they would like and can offer on a low day.', 'Use it to help partners agree on helpful support before a hard day arrives.', array['Couples']::text[], '30 minutes', 'Each partner fills in their own columns separately, then they trade and talk. The partner with low mood lists what helps and what does not; the other lists what they can realistically give. Discuss gently and keep requests concrete.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me on a low day:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I can offer when you are low:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what helps me on a low day:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I can offer when you are low:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('time-blindness-visual-timeline-builder', 'Time Blindness Visual Timeline Builder', 'worksheet'::resource_kind, 'A worksheet for laying out a task as a visual timeline with checkpoints.', 'Use it to help a client see the time a task takes before starting it.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a real task and have the client guess its length, then break it into steps with checkpoints on a drawn timeline. Compare the guess to what happened next session. Stay curious; an off guess is data about time, not about effort.', '[{"id": "f0", "type": "textarea", "label": "The task and my time guess:"}, {"id": "f1", "type": "textarea", "label": "The steps in order:"}, {"id": "f2", "type": "textarea", "label": "Where I will check the clock:"}, {"id": "f3", "type": "textarea", "label": "How long it actually took:"}]'::jsonb, array['ADHD', 'time management', 'planning']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('start-barrier-troubleshooting-sheet', 'Start Barrier Troubleshooting Sheet', 'cbt'::resource_kind, 'A sheet for finding what blocks starting a task and choosing one change to the setup.', 'Use it to help a client lower the friction of getting started.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through one avoided task and ask what makes the first step hard: unclear, boring, too big or distracting. Pick one environmental change. Keep it practical and non-shaming; the client is solving a design problem.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off:"}, {"id": "f1", "type": "textarea", "label": "What makes starting it hard:"}, {"id": "f2", "type": "textarea", "label": "One change that would make it easier:"}, {"id": "f3", "type": "textarea", "label": "The first two-minute step:"}]'::jsonb, array['ADHD', 'task initiation', 'problem solving']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('brain-break-obstacle-course-craft', 'Brain Break Obstacle Course Craft', 'kids'::resource_kind, 'A build-it activity where a child sets up a short home obstacle course for movement breaks.', 'Use it to help a child plan movement breaks that fit around homework.', array['Children']::text[], '30 minutes', 'The child and parent build a short course from pillows and tape and choose three breaks to use. The parent sets a timer and joins in sometimes. Keep breaks short and predictable so returning to work stays easy.', '[{"id": "f0", "type": "textarea", "label": "My three break moves:"}, {"id": "f1", "type": "textarea", "label": "When I take a break during homework:"}, {"id": "f2", "type": "textarea", "label": "How my body feels after the course:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up does to help:"}]'::jsonb, array['ADHD', 'children', 'movement', 'homework']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('beat-the-clock-chore-relay', 'Beat the Clock Chore Relay', 'game'::resource_kind, 'A relay game where players guess and then race a timer through short tasks.', 'Use it to help players practice estimating and pacing short tasks.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Each player guesses how long a short task will take, then does it against a timer. Rules: closest guess earns a point, and everyone gets a turn. Debrief on who over- or underestimated and what they could try next time.', '[{"id": "f0", "type": "textarea", "label": "My guess and the real time:"}, {"id": "f1", "type": "textarea", "label": "Whether I guessed too long or too short:"}, {"id": "f2", "type": "textarea", "label": "A trick that helped me stay on task:"}, {"id": "f3", "type": "textarea", "label": "A task I will time at home:"}]'::jsonb, array['ADHD', 'game', 'time estimation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('shared-reminder-system-agreement', 'Shared Reminder System Agreement', 'couples'::resource_kind, 'An agreement where partners decide how reminders are given and received without nagging.', 'Use it to help partners agree on reminders that help rather than sting.', array['Couples']::text[], '30 minutes', 'One partner says how they prefer to be reminded and the other says what they can give. Agree on a tool, a tone and how many nudges. Review after a week; expect to tweak wording and timing.', '[{"id": "f0", "type": "textarea", "label": "How I would like to be reminded:"}, {"id": "f1", "type": "textarea", "label": "How I would rather not be reminded:"}, {"id": "f2", "type": "textarea", "label": "What I can do when I forget:"}, {"id": "f3", "type": "textarea", "label": "What we will try this week:"}]'::jsonb, array['ADHD', 'couples', 'communication']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('urge-trigger-and-response-map', 'Urge Trigger and Response Map', 'worksheet'::resource_kind, 'A map of the people, places, feelings and times that come before an urge for substance use.', 'Use it to help a client see patterns in their urges and choose where to intervene.', array['Adults']::text[], '30 minutes', 'Build the map from recent real examples without judgment. Mark which triggers the client can avoid, which they can change and which they must plan to face. Keep the language about substance use and urges, not about the person.', '[{"id": "f0", "type": "textarea", "label": "Places and people near my urges:"}, {"id": "f1", "type": "textarea", "label": "Feelings that come before them:"}, {"id": "f2", "type": "textarea", "label": "Times of day they show up:"}, {"id": "f3", "type": "textarea", "label": "One trigger I could change this week:"}]'::jsonb, array['addiction', 'urges', 'triggers']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('urge-surfing-rating-log', 'Urge Surfing Rating Log', 'cbt'::resource_kind, 'A log for riding out an urge and rating its strength every few minutes.', 'Use it to help a client see that urges rise and fall.', array['Adults']::text[], 'One week', 'Teach the client to notice the urge, breathe and rate it every few minutes. Ask them to log the peak and how long it lasted. Review together without promising it will always work; the log is for learning about their urges.', '[{"id": "f0", "type": "textarea", "label": "The urge and what set it off:"}, {"id": "f1", "type": "textarea", "label": "My rating at the start:"}, {"id": "f2", "type": "textarea", "label": "My rating after ten minutes:"}, {"id": "f3", "type": "textarea", "label": "What I did while it passed:"}]'::jsonb, array['addiction', 'urges', 'urge surfing']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-using-versus-waiting', 'Pros and Cons of Using Versus Waiting', 'dbt'::resource_kind, 'A DBT pros and cons grid comparing acting on an urge with waiting it out.', 'Use it to help a client weigh short-term and long-term effects of substance use.', array['Adults']::text[], '25 minutes', 'Fill all four boxes honestly, including what substance use gives the client. Treat that without judgment so the exercise stays credible. Look at which side holds up when the urge is strong and revisit during a calm moment.', '[{"id": "f0", "type": "textarea", "label": "Pros of acting on the urge:"}, {"id": "f1", "type": "textarea", "label": "Cons of acting on the urge:"}, {"id": "f2", "type": "textarea", "label": "Pros of waiting:"}, {"id": "f3", "type": "textarea", "label": "Cons of waiting:"}]'::jsonb, array['addiction', 'pros and cons', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-an-urge-practice-page', 'Willing to Feel an Urge Practice Page', 'act'::resource_kind, 'A page for making room for an urge and choosing a values-based action anyway.', 'Use it to help a client carry an urge while doing something that matters to them.', array['Adults']::text[], '25 minutes', 'Ask where in the body the urge sits and practice making room for it for a minute. Then choose a values-based action to do with the urge present. Be honest that urges can be uncomfortable and that willingness is a choice made again each time.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body:"}, {"id": "f1", "type": "textarea", "label": "What the urge tells me to do:"}, {"id": "f2", "type": "textarea", "label": "What matters to me that I could do instead:"}, {"id": "f3", "type": "textarea", "label": "What I will do next time it shows up:"}]'::jsonb, array['addiction', 'willingness', 'values']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('recovery-support-agreement-for-partners', 'Recovery Support Agreement for Partners', 'couples'::resource_kind, 'A page where partners write what support looks like and how to talk about urges or slips.', 'Use it to help partners agree on supportive responses and clear boundaries.', array['Couples']::text[], '35 minutes', 'Each partner writes what helps and what hurts when substance use comes up, then they share. Agree on a way to raise concerns calmly and on boundaries that protect both. Keep it about behaviors and requests, not blame.', '[{"id": "f0", "type": "textarea", "label": "What support from you looks like to me:"}, {"id": "f1", "type": "textarea", "label": "What I need to hear when I have an urge:"}, {"id": "f2", "type": "textarea", "label": "What I need to stay safe and steady:"}, {"id": "f3", "type": "textarea", "label": "How we will talk if something slips:"}]'::jsonb, array['addiction', 'couples', 'boundaries']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('anger-warning-signs-body-scan-sheet', 'Anger Warning Signs Body Scan Sheet', 'worksheet'::resource_kind, 'A sheet for mapping early body signs of rising anger and a step to take at each level.', 'Use it to help a client catch anger early and pick a response by level.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client recall a recent surge and mark where they felt it first. Build three levels (early, rising, boiling) and one step for each. Practice the early step in session. The aim is choice, not suppression.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first in my body:"}, {"id": "f1", "type": "textarea", "label": "Early signs, rising signs, boiling signs:"}, {"id": "f2", "type": "textarea", "label": "What I can do at the early level:"}, {"id": "f3", "type": "textarea", "label": "What I do when I am already boiling:"}]'::jsonb, array['anger management', 'warning signs', 'body']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('hot-thought-cool-thought-swap-sheet', 'Hot Thought Cool Thought Swap Sheet', 'cbt'::resource_kind, 'A sheet pairing an anger-fueling thought with a cooler, more balanced one.', 'Use it to help a client see how their interpretation feeds anger.', array['Adults', 'Teens']::text[], '20 minutes', 'Take a recent trigger and write the thought that fired. Ask what else could be true and write a cooler version. Check that the cool thought feels believable; forced positivity tends to backfire. Rate anger before and after.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "The hot thought:"}, {"id": "f2", "type": "textarea", "label": "A cooler thought that is still honest:"}, {"id": "f3", "type": "textarea", "label": "My anger rating before and after:"}]'::jsonb, array['anger management', 'thoughts', 'reframing']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('take-a-break-with-a-return-plan', 'Take a Break With a Return Plan', 'dbt'::resource_kind, 'A plan for stepping away from a heated moment and coming back to repair.', 'Use it to help a client leave a conflict safely and return when calmer.', array['Adults', 'Couples']::text[], '25 minutes', 'Agree on a signal, a length of time out and an activity that actually calms rather than rehearses the argument. The plan includes a return time. Practice saying the phrase aloud. Review how the break and the return went.', '[{"id": "f0", "type": "textarea", "label": "My signal to pause:"}, {"id": "f1", "type": "textarea", "label": "What I will do during the break:"}, {"id": "f2", "type": "textarea", "label": "When I will come back:"}, {"id": "f3", "type": "textarea", "label": "What I will say when I return:"}]'::jsonb, array['anger management', 'time out', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('volcano-craft-with-cooling-steps', 'Volcano Craft With Cooling Steps', 'kids'::resource_kind, 'A craft where a child builds a paper volcano and writes cooling steps on the slopes.', 'Use it to help a child learn what to do as anger climbs.', array['Children']::text[], '30 minutes', 'Build the volcano with levels from calm to erupting and write one cooling step on each, such as squeezing a pillow or counting. The parent practices the steps with the child at calm times and praises using them. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "What my body does as I get mad:"}, {"id": "f1", "type": "textarea", "label": "Three cooling steps I like:"}, {"id": "f2", "type": "textarea", "label": "Who I can ask for help:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do to help:"}]'::jsonb, array['anger management', 'children', 'craft', 'calming']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('cool-words-charades', 'Cool Words Charades', 'game'::resource_kind, 'A charades game acting out feelings and the calm choices that follow.', 'Use it to help players name anger levels and rehearse calm responses.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players draw a card describing a frustrating situation and act out a calm response while the others guess. Rules: no mocking, anyone may pass. Debrief which responses felt doable and what made them hard.', '[{"id": "f0", "type": "textarea", "label": "The situation I drew and the response I acted:"}, {"id": "f1", "type": "textarea", "label": "A response I saw that I could use:"}, {"id": "f2", "type": "textarea", "label": "What makes calm hard for me:"}, {"id": "f3", "type": "textarea", "label": "One I will try this week:"}]'::jsonb, array['anger management', 'game', 'role-play']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('doubt-versus-certainty-sorting-page', 'Doubt Versus Certainty Sorting Page', 'worksheet'::resource_kind, 'A page for sorting worries into what can be known and what must stay uncertain.', 'Use it to help a client see which doubts reassurance can never settle.', array['Adults', 'Teens']::text[], '25 minutes', 'List recent doubts and sort them with the client. Notice how chasing certainty costs time. Stay out of the reassurance role yourself; focus on practicing a little more uncertainty at a chosen pace.', '[{"id": "f0", "type": "textarea", "label": "A doubt that keeps coming back:"}, {"id": "f1", "type": "textarea", "label": "What I do to try to feel sure:"}, {"id": "f2", "type": "textarea", "label": "How long that takes me each day:"}, {"id": "f3", "type": "textarea", "label": "A small bit of uncertainty I could try to leave alone:"}]'::jsonb, array['OCD', 'uncertainty', 'reassurance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('exposure-ladder-with-ritual-notes', 'Exposure Ladder With Ritual Notes', 'cbt'::resource_kind, 'A ladder of situations ranked by distress, with a note on the ritual urge at each step.', 'Use it to help a client plan graded practice at a pace they choose.', array['Adults', 'Teens']::text[], 'Full session', 'Build the ladder together from 0 to 100 distress and start low. Have the client choose the first rung and rate distress and the ritual urge before and after. Do not push; the client controls the pace. Plan the next rung only if they are ready.', '[{"id": "f0", "type": "textarea", "label": "The situation on this rung:"}, {"id": "f1", "type": "textarea", "label": "Distress rating before and after:"}, {"id": "f2", "type": "textarea", "label": "The ritual urge and what I did:"}, {"id": "f3", "type": "textarea", "label": "The next rung I am ready for:"}]'::jsonb, array['OCD', 'exposure', 'ladder']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('thought-is-just-a-thought-cards', 'Thought Is Just a Thought Cards', 'act'::resource_kind, 'A set of cards that practice noticing an intrusive thought without arguing or acting on it.', 'Use it to help a client step back from sticky thoughts with some humor.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the client''s intrusive thoughts on cards and try phrases like ''I am having the thought that''. Try singing the thought or reading it slowly. The aim is a looser relationship with the thought, not making it go away.', '[{"id": "f0", "type": "textarea", "label": "A thought that sticks:"}, {"id": "f1", "type": "textarea", "label": "How I say it with ''I am having the thought that'':"}, {"id": "f2", "type": "textarea", "label": "What happens when I read it slowly:"}, {"id": "f3", "type": "textarea", "label": "What I would rather be doing:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('bossy-brain-name-and-draw', 'Bossy Brain Name and Draw', 'kids'::resource_kind, 'A drawing activity where a child names and pictures the bossy brain and writes back to it.', 'Use it to help a child separate themselves from the urgent voice that demands rituals.', array['Children']::text[], '30 minutes', 'The child draws the bossy brain and gives it a silly name, then writes or dictates a reply. The parent learns to say ''sounds like the bossy brain'' rather than give reassurance or join rituals. Review what the child tried.', '[{"id": "f0", "type": "textarea", "label": "What my bossy brain looks like:"}, {"id": "f1", "type": "textarea", "label": "What it says to me:"}, {"id": "f2", "type": "textarea", "label": "What I want to say back:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will say to help:"}]'::jsonb, array['OCD', 'children', 'externalizing', 'parents']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('maybe-is-okay-dare-deck', 'Maybe Is Okay Dare Deck', 'game'::resource_kind, 'A card game of small, agreed dares that practice not checking or redoing.', 'Use it to help players try tiny steps of tolerating uncertainty with support.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player writes a few easy dares at a level they choose. They draw and try one while rating discomfort. Rules: the player always sets their own level and may pass. Debrief on what they noticed when they stayed with it.', '[{"id": "f0", "type": "textarea", "label": "The dare I chose:"}, {"id": "f1", "type": "textarea", "label": "Discomfort before and after:"}, {"id": "f2", "type": "textarea", "label": "What I did instead of a ritual:"}, {"id": "f3", "type": "textarea", "label": "The next dare I want to try:"}]'::jsonb, array['OCD', 'game', 'exposure']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('panic-surge-minute-by-minute-chart', 'Panic Surge Minute-by-Minute Chart', 'worksheet'::resource_kind, 'A page for charting a panic wave from first sensation to when it eases.', 'Use it to help a client see that panic rises, peaks and passes.', array['Adults', 'Teens']::text[], '25 minutes', 'Chart a recent wave minute by minute with sensations and thoughts. Note when it peaked and when it began to ease. Use the timeline to build a plan, and let the client lead the pace of the discussion.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I first noticed:"}, {"id": "f1", "type": "textarea", "label": "The thoughts that came with it:"}, {"id": "f2", "type": "textarea", "label": "When it peaked and when it eased:"}, {"id": "f3", "type": "textarea", "label": "What I did that helped:"}]'::jsonb, array['panic attacks', 'timeline', 'sensations']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('body-sensation-interpretation-swap-sheet', 'Body Sensation Interpretation Swap Sheet', 'cbt'::resource_kind, 'A sheet for catching a catastrophic reading of a body sensation and writing a calmer one.', 'Use it to help a client reinterpret sensations during panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Pair a sensation, such as a racing heart, with the feared meaning and then a calmer alternative that fits the facts. Encourage checking in with a clinician or doctor about health questions rather than guessing. Practice reading the card aloud.', '[{"id": "f0", "type": "textarea", "label": "The sensation I noticed:"}, {"id": "f1", "type": "textarea", "label": "What I feared it meant:"}, {"id": "f2", "type": "textarea", "label": "A calmer explanation that fits:"}, {"id": "f3", "type": "textarea", "label": "How strongly I believed each, zero to ten:"}]'::jsonb, array['panic attacks', 'interpretation', 'sensations']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('tip-skills-quick-reset-card', 'TIP Skills Quick Reset Card', 'dbt'::resource_kind, 'A card of the temperature, intense exercise, paced breathing and paired relaxation steps for quick resets.', 'Use it to help a client bring down intense arousal quickly and safely.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach each skill and let the client try them in session. Check for health reasons to avoid cold water or hard exercise first. Have them pick two they like and rehearse when calm so they are ready during a surge.', '[{"id": "f0", "type": "textarea", "label": "The skills I picked:"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body after trying them:"}, {"id": "f2", "type": "textarea", "label": "Where I will keep my card:"}, {"id": "f3", "type": "textarea", "label": "When I will practice:"}]'::jsonb, array['panic attacks', 'TIP skills', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('breathing-buddy-stuffed-animal-practice', 'Breathing Buddy Stuffed Animal Practice', 'kids'::resource_kind, 'A play activity where a child breathes slowly with a stuffed animal on their belly.', 'Use it to help a child practice slow breathing in a playful, familiar way.', array['Children']::text[], '15 minutes', 'The child lies down with a stuffed animal on their belly and watches it rise and fall. The parent practices too and uses the same words when the child is upset. Keep it short, fun and part of the daily routine.', '[{"id": "f0", "type": "textarea", "label": "My buddy''s name:"}, {"id": "f1", "type": "textarea", "label": "How my buddy moves when I breathe slowly:"}, {"id": "f2", "type": "textarea", "label": "When I can do this at home:"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward:"}]'::jsonb, array['panic attacks', 'children', 'breathing', 'play']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('sensations-welcome-anyway-practice', 'Sensations Welcome Anyway Practice', 'act'::resource_kind, 'A practice for letting panic sensations come while staying with the task at hand.', 'Use it to help a client stop fighting sensations and keep doing what matters.', array['Adults']::text[], '25 minutes', 'Describe sensations as waves and practice noticing them without trying to stop them. Link the practice to a value the client wants to keep doing. Be honest that this takes repetition, and stay with small experiments.', '[{"id": "f0", "type": "textarea", "label": "What I usually do when panic starts:"}, {"id": "f1", "type": "textarea", "label": "What happens when I make room instead:"}, {"id": "f2", "type": "textarea", "label": "What I want to keep doing even if it comes:"}, {"id": "f3", "type": "textarea", "label": "One place I will practice:"}]'::jsonb, array['panic attacks', 'willingness', 'acceptance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('routine-builder-for-rough-mornings', 'Routine Builder for Rough Mornings', 'worksheet'::resource_kind, 'A worksheet for mapping a morning routine step by step with the child''s input.', 'Use it to help a parent build a predictable routine that reduces daily friction.', array['Adults']::text[], '30 minutes', 'Walk through a typical morning and find where it bogs down. Build a short routine with the child''s input, using pictures for younger children. Pick one step to change this week rather than overhauling everything.', '[{"id": "f0", "type": "textarea", "label": "The hardest part of our morning:"}, {"id": "f1", "type": "textarea", "label": "Steps in order, with my child''s ideas:"}, {"id": "f2", "type": "textarea", "label": "One step I will change this week:"}, {"id": "f3", "type": "textarea", "label": "How I will praise what goes well:"}]'::jsonb, array['parenting', 'routines', 'mornings']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('parent-trigger-and-calm-response-planner', 'Parent Trigger and Calm Response Planner', 'cbt'::resource_kind, 'A planner linking the moments that set a parent off with a thought and a calmer response.', 'Use it to help a parent respond rather than react in hard moments.', array['Adults']::text[], '25 minutes', 'Choose a recurring trigger and trace the thought and feeling behind it. Write one calmer response the parent can say or do. Normalize being frustrated; the goal is a pause, not perfection. Rehearse the line aloud.', '[{"id": "f0", "type": "textarea", "label": "The moment that sets me off:"}, {"id": "f1", "type": "textarea", "label": "What I tell myself then:"}, {"id": "f2", "type": "textarea", "label": "A calmer line I can say:"}, {"id": "f3", "type": "textarea", "label": "What I will do if I still lose my cool:"}]'::jsonb, array['parenting', 'triggers', 'self-regulation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('family-rules-poster-and-rewards-chart', 'Family Rules Poster and Rewards Chart', 'kids'::resource_kind, 'A poster the family designs with a few positive rules and a simple chart for noticing effort.', 'Use it to help a family agree on clear expectations in kid-friendly form.', array['Children', 'Adults']::text[], '30 minutes', 'The child helps decorate a poster of three or four rules written in positive words. The parent notices and names effort and uses the chart for small, steady rewards. Review in a week and adjust rules that are not working.', '[{"id": "f0", "type": "textarea", "label": "Our three rules:"}, {"id": "f1", "type": "textarea", "label": "Something I did well this week:"}, {"id": "f2", "type": "textarea", "label": "A reward I would like:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will say when I follow a rule:"}]'::jsonb, array['parenting', 'children', 'rules', 'praise']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('feelings-face-role-play-game', 'Feelings Face Role-Play Game', 'game'::resource_kind, 'A role-play game where parent and child act out feelings and responses by taking turns.', 'Use it to help parent and child practice naming feelings and responding kindly.', array['Children', 'Adults']::text[], '20 minutes', 'Take turns drawing a feeling card and acting it out while the other guesses and responds. Rules: be kind, switch roles, either may pass. Debrief on what helped each person feel heard.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted:"}, {"id": "f1", "type": "textarea", "label": "What the other person said that helped:"}, {"id": "f2", "type": "textarea", "label": "A time I felt that this week:"}, {"id": "f3", "type": "textarea", "label": "One kind response I will try at home:"}]'::jsonb, array['parenting', 'game', 'emotion coaching']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('co-parenting-agreement-on-discipline', 'Co-Parenting Agreement on Discipline', 'couples'::resource_kind, 'A page where co-parents agree on a few shared responses and how to back each other up.', 'Use it to help co-parents stay consistent and avoid undermining one another.', array['Couples']::text[], '35 minutes', 'Each parent lists two behaviors they want handled the same way, then they agree on one response each. Decide how to disagree out of earshot. Keep the list short; start small and review in two weeks.', '[{"id": "f0", "type": "textarea", "label": "Behaviors we want to handle together:"}, {"id": "f1", "type": "textarea", "label": "The response we will both use:"}, {"id": "f2", "type": "textarea", "label": "How we will disagree privately:"}, {"id": "f3", "type": "textarea", "label": "How we will support each other in the moment:"}]'::jsonb, array['parenting', 'couples', 'consistency']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('sleep-and-support-shift-planner-for-new-parents', 'Sleep and Support Shift Planner for New Parents', 'worksheet'::resource_kind, 'A planner for trading night shifts and lining up help in the early weeks with a baby.', 'Use it to help new parents protect rest and ask for practical support.', array['Adults', 'Couples']::text[], '30 minutes', 'Map nights and who covers which stretch, and list people who could bring a meal or watch the baby for an hour. Help the client practice asking. If low mood or worry feels heavy or lasts, encourage them to tell their provider; 988 can be called or texted for crisis support at any time.', '[{"id": "f0", "type": "textarea", "label": "Who can cover which stretch of the night:"}, {"id": "f1", "type": "textarea", "label": "People who offered help and what I will ask for:"}, {"id": "f2", "type": "textarea", "label": "My rest plan this week:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell if things feel heavy:"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('enough-for-today-new-parent-thought-sheet', 'Enough For Today New Parent Thought Sheet', 'cbt'::resource_kind, 'A sheet for catching perfectionist thoughts about parenting and writing good-enough ones.', 'Use it to help a new parent loosen the pressure to do everything right.', array['Adults']::text[], '20 minutes', 'Collect the ''should'' thoughts that weigh on the client and write a good-enough alternative for each. Ask what they would tell a friend. Keep the tone warm; many new parents feel unseen in this stage.', '[{"id": "f0", "type": "textarea", "label": "A should that is weighing on me:"}, {"id": "f1", "type": "textarea", "label": "Where I learned it:"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend:"}, {"id": "f3", "type": "textarea", "label": "A good-enough version I can live with:"}]'::jsonb, array['perinatal and postpartum', 'perfectionism', 'self-compassion']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('moments-of-joy-and-weight-page', 'Moments of Joy and Weight Page', 'act'::resource_kind, 'A page for noticing both the hard and the tender in early parenting without choosing one.', 'Use it to help a parent hold mixed feelings while caring for a baby.', array['Adults']::text[], '25 minutes', 'Invite the client to name hard moments and tender ones in the same breath. Normalize mixed feelings without minimizing them. Choose one value-guided act of care for themselves. If distress is heavy, help them reach their provider or call or text 988.', '[{"id": "f0", "type": "textarea", "label": "A hard moment this week:"}, {"id": "f1", "type": "textarea", "label": "A tender moment this week:"}, {"id": "f2", "type": "textarea", "label": "What kind of parent I want to be on a rough day:"}, {"id": "f3", "type": "textarea", "label": "One small act of care for myself:"}]'::jsonb, array['perinatal and postpartum', 'values', 'mixed feelings']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('division-of-labor-and-appreciation-talk', 'Division of Labor and Appreciation Talk', 'couples'::resource_kind, 'A conversation guide for naming who does what with the baby and thanking each other.', 'Use it to help new-parent partners share load and notice each other''s effort.', array['Couples']::text[], '35 minutes', 'Each partner lists what they do, unseen tasks included, and one thing they appreciate about the other. Then trade and choose one task to swap. Keep an eye on resentment and pace the talk so it does not become a scoreboard.', '[{"id": "f0", "type": "textarea", "label": "Tasks I do that nobody sees:"}, {"id": "f1", "type": "textarea", "label": "Something I appreciate about you:"}, {"id": "f2", "type": "textarea", "label": "One task I would like to share more:"}, {"id": "f3", "type": "textarea", "label": "How we will check in weekly:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'division of labor']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('wise-mind-moment-for-overwhelmed-nights', 'Wise Mind Moment for Overwhelmed Nights', 'dbt'::resource_kind, 'A card for pausing in an overwhelmed moment and finding a wise-mind next step.', 'Use it to help a parent steady themselves in a hard middle-of-the-night moment.', array['Adults']::text[], '20 minutes', 'Teach the client to pause, breathe, and ask what emotion mind says and what reason says before finding the wise next step. Practice during the day. Add soothing items they can reach at night.', '[{"id": "f0", "type": "textarea", "label": "What emotion mind says right now:"}, {"id": "f1", "type": "textarea", "label": "What reason says:"}, {"id": "f2", "type": "textarea", "label": "What my wise mind would do next:"}, {"id": "f3", "type": "textarea", "label": "Who I can reach out to:"}]'::jsonb, array['perinatal and postpartum', 'wise mind', 'overwhelm']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('meet-your-critic-conversation-page', 'Meet Your Critic Conversation Page', 'worksheet'::resource_kind, 'A page for interviewing the inner critic, then writing what a fair friend would say.', 'Use it to help a client see their inner critic''s patterns and answer back.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to give the critic a name, write its common lines and notice what it is trying to do for them. Then write a fair response. Do not argue with the critic; just practice a different voice.', '[{"id": "f0", "type": "textarea", "label": "The critic''s favorite lines:"}, {"id": "f1", "type": "textarea", "label": "What it is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "What a fair friend would say:"}, {"id": "f3", "type": "textarea", "label": "A line I will use this week:"}]'::jsonb, array['self-esteem', 'inner critic', 'self-talk']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('daily-proof-against-the-harsh-verdict-file', 'Daily Proof Against the Harsh Verdict File', 'cbt'::resource_kind, 'A file for collecting daily proof of effort, kindness and skill to balance a negative self-view.', 'Use it to help a client weigh evidence that fits a negative core belief.', array['Adults', 'Teens']::text[], 'Two weeks', 'Name the belief, then log daily evidence that does not fit it, however small. At review, read the file back and ask what the client notices. Evidence takes time to land, so expect gradual change.', '[{"id": "f0", "type": "textarea", "label": "The belief about myself I am testing:"}, {"id": "f1", "type": "textarea", "label": "Evidence today that does not fit it:"}, {"id": "f2", "type": "textarea", "label": "Something I handled well:"}, {"id": "f3", "type": "textarea", "label": "What I notice when I read it back:"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('the-one-who-notices-self-judgments-page', 'The One Who Notices Self-Judgments Page', 'act'::resource_kind, 'A page for noticing the part of a client that observes harsh self-judgments without being them.', 'Use it to help a client step back from self-judgments and keep acting on values.', array['Adults']::text[], '25 minutes', 'Invite the client to notice that they can watch their thoughts about themselves. Practice naming a judgment and stepping back to the observer. Link it to a small action that matters to them.', '[{"id": "f0", "type": "textarea", "label": "A harsh judgment I hear about myself:"}, {"id": "f1", "type": "textarea", "label": "What I notice when I just watch it:"}, {"id": "f2", "type": "textarea", "label": "What matters more than the judgment:"}, {"id": "f3", "type": "textarea", "label": "A step I will take anyway:"}]'::jsonb, array['self-esteem', 'self-as-context', 'defusion']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('all-about-me-treasure-box-craft', 'All About Me Treasure Box Craft', 'kids'::resource_kind, 'A craft where a child decorates a box and fills it with objects and drawings that show what they like about themselves.', 'Use it to help a child build a concrete reminder of their strengths.', array['Children']::text[], '30 minutes', 'The child decorates a shoebox and fills it with drawings and small objects. The parent adds notes naming specific effort, not just looks or outcomes. Revisit the box when the child feels down.', '[{"id": "f0", "type": "textarea", "label": "Things I am good at:"}, {"id": "f1", "type": "textarea", "label": "Things I like about myself:"}, {"id": "f2", "type": "textarea", "label": "Something kind I did this week:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up wrote for my box:"}]'::jsonb, array['self-esteem', 'children', 'craft', 'strengths']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('spotted-strength-round-robin', 'Spotted Strength Round Robin', 'game'::resource_kind, 'A turn-taking game where players name a strength they saw in another person.', 'Use it to help a group give and receive specific, sincere strengths.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player draws a prompt and names a specific strength they saw in another player. Rules: be specific and sincere, no appearance comments, and anyone may pass. Debrief on how receiving felt.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me:"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it:"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone else:"}, {"id": "f3", "type": "textarea", "label": "One I will own this week:"}]'::jsonb, array['self-esteem', 'game', 'strengths']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('social-situation-comfort-ladder', 'Social Situation Comfort Ladder', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest for planned, gradual practice.', 'Use it to help a client choose graded social steps at their own pace.', array['Adults', 'Teens']::text[], '30 minutes', 'List situations and rate how hard each feels, then pick the lowest rung to try first. Let the client set the pace. Review what they noticed afterward and what they would do differently.', '[{"id": "f0", "type": "textarea", "label": "Easier situations I could try:"}, {"id": "f1", "type": "textarea", "label": "Harder ones I avoid:"}, {"id": "f2", "type": "textarea", "label": "The first step I will take:"}, {"id": "f3", "type": "textarea", "label": "What I will notice afterward:"}]'::jsonb, array['social anxiety', 'ladder', 'gradual practice']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('attention-outward-conversation-practice', 'Attention Outward Conversation Practice', 'cbt'::resource_kind, 'A practice for shifting attention from self-monitoring to the other person and the room.', 'Use it to help a client notice how self-focus affects how a conversation feels.', array['Adults', 'Teens']::text[], '25 minutes', 'Contrast a short chat with attention on self and then on the other person, and compare the experience. Keep it experimental and kind. Plan one real conversation to try the outward focus.', '[{"id": "f0", "type": "textarea", "label": "What I watched in myself during the chat:"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I focused on the other person:"}, {"id": "f2", "type": "textarea", "label": "How anxious I felt each time:"}, {"id": "f3", "type": "textarea", "label": "A conversation I will try this with:"}]'::jsonb, array['social anxiety', 'attention', 'experiment']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('values-before-comfort-social-page', 'Values Before Comfort Social Page', 'act'::resource_kind, 'A page for choosing a social step because it matters, not because it feels comfortable.', 'Use it to help a client act on connection values with nerves present.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what kind of friend or colleague the client wants to be and choose one step that expresses it. Nerves may come along. Review the step and what the client did with the nerves.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be with others:"}, {"id": "f1", "type": "textarea", "label": "A step that fits that:"}, {"id": "f2", "type": "textarea", "label": "What my nerves tell me:"}, {"id": "f3", "type": "textarea", "label": "What I will do with them:"}]'::jsonb, array['social anxiety', 'values', 'connection']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('building-mastery-for-social-confidence', 'Building Mastery for Social Confidence', 'dbt'::resource_kind, 'A page for planning small social wins and noting how they feel afterward.', 'Use it to help a client build confidence by doing manageable social tasks.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one small social task a day, such as saying hello, and log it. Reviewing the log together shows growing skill. Add a pleasant activity afterward so the experience ends well.', '[{"id": "f0", "type": "textarea", "label": "Today''s small social task:"}, {"id": "f1", "type": "textarea", "label": "How hard it felt before and after:"}, {"id": "f2", "type": "textarea", "label": "The pleasant thing I did afterward:"}, {"id": "f3", "type": "textarea", "label": "Tomorrow''s task:"}]'::jsonb, array['social anxiety', 'mastery', 'skills']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('small-talk-starter-card-game', 'Small Talk Starter Card Game', 'game'::resource_kind, 'A card game of conversation openers to practice in a low-stakes setting.', 'Use it to help players practice starting and ending short conversations.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Players draw an opener, try it with a partner and swap. Rules: kind responses only, anyone may pass, and short is fine. Debrief on what felt easier than expected.', '[{"id": "f0", "type": "textarea", "label": "The opener I tried:"}, {"id": "f1", "type": "textarea", "label": "What the other person said:"}, {"id": "f2", "type": "textarea", "label": "How nervous I felt, zero to ten:"}, {"id": "f3", "type": "textarea", "label": "One I will use this week:"}]'::jsonb, array['social anxiety', 'game', 'small talk']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('grief-waves-and-anchors-journal-page', 'Grief Waves and Anchors Journal Page', 'worksheet'::resource_kind, 'A page for tracking how grief comes in waves and what helps the client stay steady.', 'Use it to help a client notice when grief rises and plan gentle supports.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to note when grief hit, what set it off and what helped. Expect no timetable. If thoughts of ending their life appear, ask in session and share that 988 can be called or texted any time.', '[{"id": "f0", "type": "textarea", "label": "When the wave came:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "What helped me stay steady:"}, {"id": "f3", "type": "textarea", "label": "One gentle plan for this week:"}]'::jsonb, array['grief and loss', 'waves', 'self-care']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('love-continues-through-me-values-page', 'Love Continues Through Me Values Page', 'act'::resource_kind, 'A page for naming what the client loved about the person and one way to carry it into life.', 'Use it to help a client honor a loss by living a value their person embodied.', array['Adults', 'Teens']::text[], '30 minutes', 'Invite the client to share what they valued about the person and choose one small action that carries it forward. Make room for pain alongside love; there is no right way to grieve.', '[{"id": "f0", "type": "textarea", "label": "What I loved most about them:"}, {"id": "f1", "type": "textarea", "label": "A value they showed me:"}, {"id": "f2", "type": "textarea", "label": "One way I can carry it this week:"}, {"id": "f3", "type": "textarea", "label": "What feels hard about it:"}]'::jsonb, array['grief and loss', 'values', 'remembering']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('memory-jar-decorating-activity', 'Memory Jar Decorating Activity', 'kids'::resource_kind, 'A craft where a child decorates a jar and fills it with notes or drawings about someone they miss.', 'Use it to help a child hold memories of a person who has died.', array['Children']::text[], '30 minutes', 'The child decorates a jar and adds drawings or dictated memories, with the parent joining in. Use plain, concrete words about death. Let the child''s pace and play lead, and watch for questions that need a gentle answer.', '[{"id": "f0", "type": "textarea", "label": "What I remember about them:"}, {"id": "f1", "type": "textarea", "label": "Something we did together:"}, {"id": "f2", "type": "textarea", "label": "How I feel when I miss them:"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to about it:"}]'::jsonb, array['grief and loss', 'children', 'craft', 'memories']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('grieving-together-and-differently-talk', 'Grieving Together and Differently Talk', 'couples'::resource_kind, 'A conversation guide for partners who grieve at different speeds and in different ways.', 'Use it to help partners understand each other''s way of grieving.', array['Couples']::text[], '35 minutes', 'Each partner describes how they grieve and what they need, then reflects back what they heard. Differences are normal. Close with one thing they can each offer this week.', '[{"id": "f0", "type": "textarea", "label": "How I grieve, in my own words:"}, {"id": "f1", "type": "textarea", "label": "What I need from you this week:"}, {"id": "f2", "type": "textarea", "label": "What I notice about how you grieve:"}, {"id": "f3", "type": "textarea", "label": "One thing we can do together:"}]'::jsonb, array['grief and loss', 'couples', 'communication']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('feeling-the-feeling-without-drowning-card', 'Feeling the Feeling Without Drowning Card', 'dbt'::resource_kind, 'A card for naming a wave of grief, riding it and returning to a steady place.', 'Use it to help a client let grief come while keeping their footing.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach naming the emotion and noticing the body, then a soothing step to return to. Practice with a small wave first. Offer pacing breaks and normalize needing them.', '[{"id": "f0", "type": "textarea", "label": "The feeling I am naming:"}, {"id": "f1", "type": "textarea", "label": "Where I feel it:"}, {"id": "f2", "type": "textarea", "label": "The soothing step I choose:"}, {"id": "f3", "type": "textarea", "label": "When I will return to my day:"}]'::jsonb, array['grief and loss', 'emotion regulation', 'mindfulness']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('relationship-needs-and-requests-inventory', 'Relationship Needs and Requests Inventory', 'worksheet'::resource_kind, 'A worksheet for turning vague complaints into specific, doable requests.', 'Use it to help a client ask for what they need in clear terms.', array['Adults']::text[], '25 minutes', 'Take a complaint such as ''you never listen'' and turn it into a specific request. Check that it is positive, doable and about behavior. Rehearse saying it aloud in session.', '[{"id": "f0", "type": "textarea", "label": "A complaint I carry:"}, {"id": "f1", "type": "textarea", "label": "The need under it:"}, {"id": "f2", "type": "textarea", "label": "A specific request I could make:"}, {"id": "f3", "type": "textarea", "label": "How I will say it kindly:"}]'::jsonb, array['relationship issues', 'requests', 'communication']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('mid-argument-olive-branch-phrase-list', 'Mid-Argument Olive Branch Phrase List', 'couples'::resource_kind, 'A bank of phrases partners can use mid-argument to slow things down and repair.', 'Use it to help partners choose and practice repair phrases that suit them.', array['Couples']::text[], '30 minutes', 'Each partner picks phrases they could say and phrases they could accept. Practice them in a mild moment and agree what each will do when one is used. Keep it simple and playful.', '[{"id": "f0", "type": "textarea", "label": "Phrases I could say mid-argument:"}, {"id": "f1", "type": "textarea", "label": "Phrases I can accept from you:"}, {"id": "f2", "type": "textarea", "label": "What we will do once a repair is offered:"}, {"id": "f3", "type": "textarea", "label": "When we will review:"}]'::jsonb, array['relationship issues', 'couples', 'repair']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('dear-man-script-builder-for-conflicts', 'DEAR MAN Script Builder for Conflicts', 'dbt'::resource_kind, 'A script builder for describing, expressing, asserting and reinforcing in a relationship conflict.', 'Use it to help a client ask for something or say no clearly and kindly.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through each letter of DEAR MAN with a real situation and rehearse it. Prepare for the other person saying no. Note that skillful asking improves the odds, not the guarantee.', '[{"id": "f0", "type": "textarea", "label": "Describe the situation:"}, {"id": "f1", "type": "textarea", "label": "Express how I feel:"}, {"id": "f2", "type": "textarea", "label": "Assert what I ask:"}, {"id": "f3", "type": "textarea", "label": "Reinforce, stay mindful and negotiate:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('guess-versus-ask-check-sheet', 'Guess Versus Ask Check Sheet', 'cbt'::resource_kind, 'A sheet for catching assumptions about what a partner or friend thinks and checking them out.', 'Use it to help a client replace guesses about others with gentle questions.', array['Adults']::text[], '20 minutes', 'List recent assumptions about what someone else meant and the client''s reaction. Write a question that checks it. Predict the answer first and compare when the client asks.', '[{"id": "f0", "type": "textarea", "label": "What I assumed they meant:"}, {"id": "f1", "type": "textarea", "label": "How I felt and acted:"}, {"id": "f2", "type": "textarea", "label": "A question that checks it out:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['relationship issues', 'assumptions', 'communication']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('active-listening-role-play-cards', 'Active Listening Role-Play Cards', 'game'::resource_kind, 'A role-play game of speaker, listener and observer practicing reflective listening.', 'Use it to help players practice listening without fixing or defending.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Players rotate between speaker, listener and observer on mild topics. The listener reflects before responding. Rules: no advice, stay on one topic, anyone may stop. Debrief on how it felt on each side.', '[{"id": "f0", "type": "textarea", "label": "What I heard the speaker say:"}, {"id": "f1", "type": "textarea", "label": "What helped me feel heard:"}, {"id": "f2", "type": "textarea", "label": "What was hard about listening:"}, {"id": "f3", "type": "textarea", "label": "A habit I will try at home:"}]'::jsonb, array['relationship issues', 'game', 'listening']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('who-and-where-feels-safe-now-map', 'Who and Where Feels Safe Now Map', 'worksheet'::resource_kind, 'A map of the people, places and things that help a client feel safe and supported now.', 'Use it to help a client see their present support and safety resources.', array['Adults', 'Teens']::text[], '25 minutes', 'Focus on the present: who is safe, where they feel safe, what helps. Never ask the client to write about what happened. Let them stop or skip any part, and keep the pace in their hands. Offer 988 call or text if distress spikes.', '[{"id": "f0", "type": "textarea", "label": "People I trust right now:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safer:"}, {"id": "f2", "type": "textarea", "label": "Things that help me feel steady:"}, {"id": "f3", "type": "textarea", "label": "One person I will reach out to:"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-menu-for-hard-reminders', 'Distress Tolerance Menu for Hard Reminders', 'dbt'::resource_kind, 'A menu of grounding, distraction and soothing skills for when a reminder hits.', 'Use it to help a client choose skills to steady themselves when triggered.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the menu while the client is calm and rehearse two items. Skills here are for stabilizing now, not for going over events. Keep the client in control of the choice and check how each skill landed.', '[{"id": "f0", "type": "textarea", "label": "Skills that ground me:"}, {"id": "f1", "type": "textarea", "label": "Skills that distract me kindly:"}, {"id": "f2", "type": "textarea", "label": "Skills that soothe me:"}, {"id": "f3", "type": "textarea", "label": "The two I will practice this week:"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'grounding']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('my-choices-today-values-page', 'My Choices Today Values Page', 'act'::resource_kind, 'A page for naming what the client wants in their life and one choice that is theirs to make.', 'Use it to help a client reconnect with values and choice at their own pace.', array['Adults']::text[], '30 minutes', 'Center the client''s present choices and values. Offer small decisions to practice choosing, such as when to start or stop. Do not ask for details of the past, and respect any boundary the client sets.', '[{"id": "f0", "type": "textarea", "label": "What I want my life to include:"}, {"id": "f1", "type": "textarea", "label": "A choice that is mine to make this week:"}, {"id": "f2", "type": "textarea", "label": "What gets in the way:"}, {"id": "f3", "type": "textarea", "label": "Support I can ask for:"}]'::jsonb, array['sexual abuse', 'values', 'choice']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-poster-and-safe-adults-hand', 'Body Safety Rules Poster and Safe Adults Hand', 'kids'::resource_kind, 'A poster of body safety rules and a traced hand listing five safe adults to tell.', 'Use it to help a child know who to tell and that their body belongs to them.', array['Children']::text[], '30 minutes', 'The child traces a hand and writes a safe adult on each finger, then decorates a poster of simple body safety rules. If a child discloses abuse, follow your reporting duties as a mandated reporter and stay calm and supportive. The parent keeps the poster visible.', '[{"id": "f0", "type": "textarea", "label": "Five grown-ups I can tell:"}, {"id": "f1", "type": "textarea", "label": "Rules about my body that are mine:"}, {"id": "f2", "type": "textarea", "label": "What I can do if something feels wrong:"}, {"id": "f3", "type": "textarea", "label": "Who will help me:"}]'::jsonb, array['sexual abuse', 'children', 'body safety', 'safe adults']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('coping-thought-card-for-present-moments', 'Coping Thought Card for Present Moments', 'cbt'::resource_kind, 'A card with calming thoughts about the present for use when a reminder shows up.', 'Use it to help a client replace alarm in the present with grounded, true statements.', array['Adults', 'Teens']::text[], '20 minutes', 'Work from today''s thought, such as ''it is happening again'', and write a true present-focused alternative like ''I am safe in this room now''. Do not explore the event. Practice reading the card in session.', '[{"id": "f0", "type": "textarea", "label": "The thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "What is true right now:"}, {"id": "f2", "type": "textarea", "label": "A coping thought for my card:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card:"}]'::jsonb, array['sexual abuse', 'coping thoughts', 'present moment']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('coping-skills-menu-by-feeling-level', 'Coping Skills Menu by Feeling Level', 'worksheet'::resource_kind, 'A menu of coping skills sorted by how intense the feeling is, from mild to intense.', 'Use it to help a client choose a skill that fits the strength of the feeling.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort skills into low, medium and high levels. High-level skills need to be quick and physical. Have the client test one from each level between sessions and report back on what worked and what did not.', '[{"id": "f0", "type": "textarea", "label": "Skills for mild feelings:"}, {"id": "f1", "type": "textarea", "label": "Skills for medium feelings:"}, {"id": "f2", "type": "textarea", "label": "Skills for intense feelings:"}, {"id": "f3", "type": "textarea", "label": "The one I will test first:"}]'::jsonb, array['coping skills', 'menu', 'emotion regulation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('when-this-happens-i-will-plan-cards', 'When This Happens I Will Plan Cards', 'cbt'::resource_kind, 'Cards that link a known trigger to a specific coping step in an if-then plan.', 'Use it to help a client prepare for hard moments before they arrive.', array['Adults', 'Teens']::text[], '20 minutes', 'Write three if-then plans for the client''s most common triggers. Keep each step concrete and doable in a minute. Rehearse and put the card where they will see it. Review which plan was used next time.', '[{"id": "f0", "type": "textarea", "label": "If this happens:"}, {"id": "f1", "type": "textarea", "label": "Then I will:"}, {"id": "f2", "type": "textarea", "label": "What might get in the way:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself:"}]'::jsonb, array['coping skills', 'planning', 'triggers']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('accepting-what-is-today-statement-page', 'Accepting What Is Today Statement Page', 'dbt'::resource_kind, 'A page for writing statements that accept what cannot be changed right now.', 'Use it to help a client stop fighting reality and focus on what they can do.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one situation the client cannot change and write acceptance statements for it. Acceptance does not mean approval. Pair with a coping action for what can be influenced. Practice breathing with the statements.', '[{"id": "f0", "type": "textarea", "label": "The situation I cannot change today:"}, {"id": "f1", "type": "textarea", "label": "A statement that accepts it:"}, {"id": "f2", "type": "textarea", "label": "What is still in my control:"}, {"id": "f3", "type": "textarea", "label": "A coping action I will take:"}]'::jsonb, array['coping skills', 'radical acceptance', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-decorating-activity', 'Coping Toolbox Decorating Activity', 'kids'::resource_kind, 'A craft where a child decorates a box and fills it with tools that help them feel better.', 'Use it to help a child have a concrete set of calming tools at home.', array['Children']::text[], '30 minutes', 'The child decorates a shoebox and fills it with items like a stress ball, drawing paper and a feelings chart. The parent learns the tools and offers them in tough moments. Keep adding and removing tools as the child grows.', '[{"id": "f0", "type": "textarea", "label": "Tools in my box:"}, {"id": "f1", "type": "textarea", "label": "The one I like best:"}, {"id": "f2", "type": "textarea", "label": "When I will use it:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up will remind me:"}]'::jsonb, array['coping skills', 'children', 'craft', 'toolbox']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('try-it-coping-bingo-board', 'Try-It Coping Bingo Board', 'game'::resource_kind, 'A bingo game where players mark squares after trying each coping skill during play.', 'Use it to help players try a range of coping skills in a fun way.', array['Teens', 'Children', 'Groups']::text[], '25 minutes', 'Make cards with different skills and let players try each one briefly. Rules: only mark a square after trying it, and everyone may pass a square. Debrief on favorites and ones that felt hard.', '[{"id": "f0", "type": "textarea", "label": "Skills I tried:"}, {"id": "f1", "type": "textarea", "label": "My favorite:"}, {"id": "f2", "type": "textarea", "label": "The hardest one:"}, {"id": "f3", "type": "textarea", "label": "A skill I will use this week:"}]'::jsonb, array['coping skills', 'game', 'bingo']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('fear-ladder-builder-with-support-plan', 'Fear Ladder Builder With Support Plan', 'worksheet'::resource_kind, 'A worksheet for ranking feared situations and planning supports for each rung.', 'Use it to help a client plan gradual contact with what they fear.', array['Adults', 'Teens']::text[], '30 minutes', 'Rank situations from 0 to 100 and pick a low first step. Plan supports and a way to stop. The client chooses the pace and the clinician agrees on what counts as a successful step.', '[{"id": "f0", "type": "textarea", "label": "The thing I fear:"}, {"id": "f1", "type": "textarea", "label": "Situations ranked easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "My first step and support:"}, {"id": "f3", "type": "textarea", "label": "How I will know I am ready for the next:"}]'::jsonb, array['phobias', 'fear ladder', 'gradual practice']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('fear-prediction-and-safety-behavior-sheet', 'Fear Prediction and Safety Behavior Sheet', 'cbt'::resource_kind, 'A sheet that lists what a client predicts and the safety behaviors they use when facing a fear.', 'Use it to help a client see how safety behaviors keep the fear going.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the predicted outcome and the safety behaviors, such as holding a rail or looking away. Plan an experiment with fewer safety behaviors at a level the client agrees to. Compare the outcome with the prediction.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f1", "type": "textarea", "label": "What I do to feel safer:"}, {"id": "f2", "type": "textarea", "label": "The experiment with less of that:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}]'::jsonb, array['phobias', 'safety behaviors', 'experiment']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('fear-and-freedom-choice-point-page', 'Fear and Freedom Choice Point Page', 'act'::resource_kind, 'A choice point page mapping what fear pulls the client away from and toward.', 'Use it to help a client choose moving toward what matters when fear appears.', array['Adults']::text[], '25 minutes', 'Draw a choice point: what fear says, what the client does when they follow it and what they do when they move toward their values. Pick one move toward. Check the pace is theirs.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me:"}, {"id": "f1", "type": "textarea", "label": "What I do when I follow it:"}, {"id": "f2", "type": "textarea", "label": "What I would do if I moved toward what matters:"}, {"id": "f3", "type": "textarea", "label": "One move toward this week:"}]'::jsonb, array['phobias', 'choice point', 'values']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('courage-staircase-coloring-page', 'Courage Staircase Coloring Page', 'kids'::resource_kind, 'A drawing activity where a child draws a staircase of brave steps toward something scary.', 'Use it to help a child plan and celebrate small brave steps.', array['Children']::text[], '30 minutes', 'The child draws a staircase with a picture of the scary thing at the top and tiny steps below. The parent praises trying and does not force a step. Start with the lowest step and let the child color it in each time.', '[{"id": "f0", "type": "textarea", "label": "The scary thing and my feeling about it:"}, {"id": "f1", "type": "textarea", "label": "My first small step:"}, {"id": "f2", "type": "textarea", "label": "Stairs I want to add:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up helps:"}]'::jsonb, array['phobias', 'children', 'gradual practice', 'drawing']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('roll-a-small-step-dice-game', 'Roll a Small Step Dice Game', 'game'::resource_kind, 'A dice game where each roll picks a small, agreed step toward something feared.', 'Use it to help players practice small steps in a playful, supported way.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player writes small steps for their own fear, and the dice picks among steps they already accepted. Rules: players only roll for their own list, and anyone may pass. Debrief on what they noticed.', '[{"id": "f0", "type": "textarea", "label": "The step I rolled:"}, {"id": "f1", "type": "textarea", "label": "How scared I was before and after:"}, {"id": "f2", "type": "textarea", "label": "What I told myself:"}, {"id": "f3", "type": "textarea", "label": "The next step I want to try:"}]'::jsonb, array['phobias', 'game', 'dice']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('body-gratitude-for-what-it-does-page', 'Body Gratitude for What It Does Page', 'worksheet'::resource_kind, 'A page for listing what the client''s body lets them do and feel each day.', 'Use it to help a client appreciate what their body does, not how it looks.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to name functions, such as carrying groceries, hugging, dancing or resting. Keep the focus on function and feeling. Avoid comparisons and appearance language; steer back if they wander.', '[{"id": "f0", "type": "textarea", "label": "Things my body helped me do today:"}, {"id": "f1", "type": "textarea", "label": "A way my body took care of me:"}, {"id": "f2", "type": "textarea", "label": "Something I enjoy doing in my body:"}, {"id": "f3", "type": "textarea", "label": "How I will thank it this week:"}]'::jsonb, array['body image', 'gratitude', 'function']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('appearance-checking-and-comparing-log', 'Appearance Checking and Comparing Log', 'cbt'::resource_kind, 'A log noting when a client checks mirrors or compares themselves, and what follows.', 'Use it to help a client see how checking and comparing affect their mood.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note the situation, the urge to check or compare and how they felt after. Review patterns together and choose one small change, such as reducing a certain feed. Stay curious, not corrective.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I did:"}, {"id": "f1", "type": "textarea", "label": "The urge I felt:"}, {"id": "f2", "type": "textarea", "label": "How I felt afterward:"}, {"id": "f3", "type": "textarea", "label": "One small change I will try:"}]'::jsonb, array['body image', 'checking', 'comparison']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('values-beyond-appearance-compass-page', 'Values Beyond Appearance Compass Page', 'act'::resource_kind, 'A page for naming what a client wants to be about besides how they look.', 'Use it to help a client act on values when appearance thoughts are loud.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would be doing if appearance thoughts were quiet and choose a small action from that list. Thoughts may stay; the action is the focus. Revisit the action next session.', '[{"id": "f0", "type": "textarea", "label": "What I want my life to be about:"}, {"id": "f1", "type": "textarea", "label": "What appearance thoughts say:"}, {"id": "f2", "type": "textarea", "label": "An action that fits my values:"}, {"id": "f3", "type": "textarea", "label": "Support for taking it:"}]'::jsonb, array['body image', 'values', 'defusion']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('superpower-body-poster', 'Superpower Body Poster', 'kids'::resource_kind, 'A poster where a child draws themself with the superpowers their body gives them.', 'Use it to help a child value what their body can do and feel.', array['Children']::text[], '25 minutes', 'The child draws a figure and labels the body''s powers, such as running, hugging or drawing. The parent adds one and keeps comments away from looks. Hang the poster where the child sees it.', '[{"id": "f0", "type": "textarea", "label": "My body''s superpowers:"}, {"id": "f1", "type": "textarea", "label": "My favorite thing my body does:"}, {"id": "f2", "type": "textarea", "label": "How I feel when I use it:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up adds:"}]'::jsonb, array['body image', 'children', 'strengths', 'drawing']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('kind-words-for-our-selves-card-game', 'Kind Words for Our Selves Card Game', 'game'::resource_kind, 'A card game where players write and trade kind, non-appearance messages to themselves.', 'Use it to help a group practice warm self-talk beyond looks.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players write a kind self-message on a card, trade, and read the card they receive aloud as a message of support. Rules: nothing about looks, anyone may pass. Debrief on how kind words felt to say and hear.', '[{"id": "f0", "type": "textarea", "label": "The kind message I wrote:"}, {"id": "f1", "type": "textarea", "label": "The one I received:"}, {"id": "f2", "type": "textarea", "label": "How it felt to read:"}, {"id": "f3", "type": "textarea", "label": "One I will say to myself this week:"}]'::jsonb, array['body image', 'game', 'self-compassion']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('weekly-wins-and-lessons-reflection-page', 'Weekly Wins and Lessons Reflection Page', 'worksheet'::resource_kind, 'A page for recording wins, lessons and one intention at the end of each week.', 'Use it to help a client review the week and set one small intention.', array['Adults', 'Teens']::text[], '10 minutes weekly', 'Use at the start of a session as a warm-up. Ask the client to read the wins aloud first. Treat lessons as information, not failures, and let them pick the intention themselves.', '[{"id": "f0", "type": "textarea", "label": "Wins this week:"}, {"id": "f1", "type": "textarea", "label": "Something hard and what it taught me:"}, {"id": "f2", "type": "textarea", "label": "One intention for next week:"}, {"id": "f3", "type": "textarea", "label": "Who or what helped:"}]'::jsonb, array['reflection', 'weekly review']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('needs-versus-wants-sorting-mat', 'Needs Versus Wants Sorting Mat', 'worksheet'::resource_kind, 'A mat for sorting items in a client''s life into needs, wants and things that can wait.', 'Use it to help a client prioritize when many demands compete.', array['Adults']::text[], '20 minutes', 'Have the client list ten current demands and sort them on the mat. Discuss what moved and why. The sorting is theirs; you ask questions and keep out of the verdict.', '[{"id": "f0", "type": "textarea", "label": "Things pulling at me:"}, {"id": "f1", "type": "textarea", "label": "What belongs under needs:"}, {"id": "f2", "type": "textarea", "label": "What can wait:"}, {"id": "f3", "type": "textarea", "label": "The one thing I will do first:"}]'::jsonb, array['prioritizing', 'planning']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('boundary-wording-practice-sheet', 'Boundary Wording Practice Sheet', 'worksheet'::resource_kind, 'A sheet for drafting short, kind boundary sentences for specific people in a client''s life.', 'Use it to help a client rehearse saying no in plain, respectful words.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one real person and one request the client wants to decline. Draft two versions, read them aloud and choose one. Rehearse the awkward silence that may follow.', '[{"id": "f0", "type": "textarea", "label": "Who I want to set a limit with:"}, {"id": "f1", "type": "textarea", "label": "What I will say:"}, {"id": "f2", "type": "textarea", "label": "What I may feel afterward:"}, {"id": "f3", "type": "textarea", "label": "How I will respond if they push:"}]'::jsonb, array['boundaries', 'assertiveness']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('values-and-daily-calendar-match-up', 'Values and Daily Calendar Match-Up', 'worksheet'::resource_kind, 'A worksheet that lines up a client''s stated values with how their week is actually spent.', 'Use it to help a client spot gaps between what matters and how time goes.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list three values and then tally where the week''s hours went. Notice mismatches without judgment and choose one small change that moves time toward a value.', '[{"id": "f0", "type": "textarea", "label": "My top three values:"}, {"id": "f1", "type": "textarea", "label": "Where my week really goes:"}, {"id": "f2", "type": "textarea", "label": "A gap I notice:"}, {"id": "f3", "type": "textarea", "label": "One change I will try:"}]'::jsonb, array['values', 'time use']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('decision-pause-pros-cons-and-gut-check', 'Decision Pause Pros, Cons and Gut Check', 'worksheet'::resource_kind, 'A worksheet for slowing a decision by weighing pros, cons and a quiet gut check.', 'Use it to help a client make a decision with less rush and more clarity.', array['Adults', 'Teens']::text[], '20 minutes', 'Use a real pending decision. Fill in pros and cons, then ask the client to sit quietly and notice their gut reaction to each option. Decide whether to choose now or gather more information.', '[{"id": "f0", "type": "textarea", "label": "The decision in front of me:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of each choice:"}, {"id": "f2", "type": "textarea", "label": "What my gut says:"}, {"id": "f3", "type": "textarea", "label": "My next step:"}]'::jsonb, array['decisions', 'problem solving']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('thinking-traps-spotter-card', 'Thinking Traps Spotter Card', 'cbt'::resource_kind, 'A card listing common thinking traps with space for the client''s own examples.', 'Use it to help a client name thinking traps as they appear.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through the traps one at a time and have the client give an example from their week. Then practice labeling thoughts in session. Labeling is a pause, not a fix.', '[{"id": "f0", "type": "textarea", "label": "A thought from this week:"}, {"id": "f1", "type": "textarea", "label": "Which trap it might be:"}, {"id": "f2", "type": "textarea", "label": "A more balanced version:"}, {"id": "f3", "type": "textarea", "label": "How I felt before and after:"}]'::jsonb, array['thinking traps', 'cognitive restructuring']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('activity-and-mood-weekly-chart', 'Activity and Mood Weekly Chart', 'cbt'::resource_kind, 'A chart that links daily activities to mood ratings so patterns show up.', 'Use it to help a client see which activities lift or lower their mood.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to log activity and a mood rating each day. At review, look for patterns together rather than telling the client what they mean. Choose one activity to do more or less.', '[{"id": "f0", "type": "textarea", "label": "Activity this morning and my mood rating:"}, {"id": "f1", "type": "textarea", "label": "Activity this afternoon and my mood rating:"}, {"id": "f2", "type": "textarea", "label": "Activity this evening and my mood rating:"}, {"id": "f3", "type": "textarea", "label": "A pattern I notice:"}]'::jsonb, array['activity monitoring', 'mood tracking']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('try-it-and-see-experiment-sheet', 'Try It and See Experiment Sheet', 'cbt'::resource_kind, 'A planner for testing a belief with a small, safe experiment and recording the result.', 'Use it to help a client test a belief against what actually happens.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a belief with a clear, observable prediction. Plan a safe experiment, predict the result and agree on how to record it. Debrief on what was learned, including when the prediction was right.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f2", "type": "textarea", "label": "The experiment I will run:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}]'::jsonb, array['behavioral experiment', 'beliefs']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('problem-solving-steps-worksheet', 'Problem-Solving Steps Worksheet', 'cbt'::resource_kind, 'A worksheet that walks a client through defining a problem, listing options and trying one.', 'Use it to help a client turn a stuck problem into a short list of options.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose a real, specific problem. Brainstorm without judging, then weigh two or three options and pick one to try. Review next session and repeat with what was learned.', '[{"id": "f0", "type": "textarea", "label": "The problem in one sentence:"}, {"id": "f1", "type": "textarea", "label": "Options I can think of:"}, {"id": "f2", "type": "textarea", "label": "The option I will try:"}, {"id": "f3", "type": "textarea", "label": "How I will know it helped:"}]'::jsonb, array['problem solving', 'planning']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('coping-card-for-hard-moments', 'Coping Card for Hard Moments', 'cbt'::resource_kind, 'A wallet-sized card with a helpful thought, a feeling check and a first step.', 'Use it to help a client carry a short reminder into hard moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the card with the client''s own words after a thought exercise. Keep it short enough to read in ten seconds. Ask them to use it once before the next session.', '[{"id": "f0", "type": "textarea", "label": "A thought that helps:"}, {"id": "f1", "type": "textarea", "label": "What I am feeling:"}, {"id": "f2", "type": "textarea", "label": "My first step:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['coping card', 'balanced thinking']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('hexaflex-check-in-for-the-week', 'Hexaflex Check-In for the Week', 'act'::resource_kind, 'A weekly check-in touching the six ACT processes in the client''s own words.', 'Use it to help a client see which ACT process they need to practice.', array['Adults']::text[], '30 minutes', 'Walk through acceptance, defusion, present moment, self-as-context, values and committed action. Let the client circle one to work on. Keep it light, and avoid scoring.', '[{"id": "f0", "type": "textarea", "label": "Where I was open to feelings this week:"}, {"id": "f1", "type": "textarea", "label": "A thought I could step back from:"}, {"id": "f2", "type": "textarea", "label": "A value I acted on:"}, {"id": "f3", "type": "textarea", "label": "The process I want to practice next:"}]'::jsonb, array['ACT', 'hexaflex', 'weekly review']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('thought-boats-on-the-river-practice', 'Thought Boats on the River Practice', 'act'::resource_kind, 'A guided practice of placing thoughts on leaves and watching them float by.', 'Use it to help a client notice thoughts without getting carried off by them.', array['Adults', 'Teens']::text[], '15 minutes', 'Read the exercise slowly in session, then ask what it was like. If it feels forced, try other images, such as clouds. The aim is noticing, not emptying the mind.', '[{"id": "f0", "type": "textarea", "label": "The thoughts I placed on leaves:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f2", "type": "textarea", "label": "When a thought got stuck:"}, {"id": "f3", "type": "textarea", "label": "Where I could use this this week:"}]'::jsonb, array['defusion', 'mindfulness', 'ACT']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('loosening-the-grip-willingness-page', 'Loosening the Grip Willingness Page', 'act'::resource_kind, 'A page using the finger trap image to explore the cost of struggling against feelings.', 'Use it to help a client see what struggling costs and what willingness offers.', array['Adults']::text[], '20 minutes', 'If you have a finger trap, let the client try it. Then ask what they do when a feeling grips them and what it costs. Move toward willingness, not forced positivity.', '[{"id": "f0", "type": "textarea", "label": "What I do when a feeling grips me:"}, {"id": "f1", "type": "textarea", "label": "What that costs me:"}, {"id": "f2", "type": "textarea", "label": "What it would look like to loosen my grip:"}, {"id": "f3", "type": "textarea", "label": "One place I will practice:"}]'::jsonb, array['willingness', 'acceptance', 'ACT']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('committed-action-weekly-plan', 'Committed Action Weekly Plan', 'act'::resource_kind, 'A plan for choosing one value-guided action each day of the week.', 'Use it to help a client turn values into steps that fit the week.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose one value and plan a small action for each day, with a backup plan for obstacles. Review which actions got done and what got in the way, with curiosity rather than judgment.', '[{"id": "f0", "type": "textarea", "label": "The value I am working on:"}, {"id": "f1", "type": "textarea", "label": "My action for each day:"}, {"id": "f2", "type": "textarea", "label": "What might get in the way:"}, {"id": "f3", "type": "textarea", "label": "My backup plan:"}]'::jsonb, array['committed action', 'values']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('observing-self-short-reflection', 'Observing Self Short Reflection', 'act'::resource_kind, 'A short reflection on the part of you that notices thoughts and feelings.', 'Use it to help a client find a steady place to observe from.', array['Adults']::text[], '15 minutes', 'Read the prompts slowly and invite the client to notice the one who notices. Keep language simple. Do not push if the idea feels abstract; use an example from their day.', '[{"id": "f0", "type": "textarea", "label": "Something I noticed in my mind today:"}, {"id": "f1", "type": "textarea", "label": "Who was noticing it:"}, {"id": "f2", "type": "textarea", "label": "What did not change while feelings came and went:"}, {"id": "f3", "type": "textarea", "label": "How I could use this tomorrow:"}]'::jsonb, array['self-as-context', 'mindfulness']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('emotion-wave-diary-card', 'Emotion Wave Diary Card', 'dbt'::resource_kind, 'A daily diary card tracking emotion intensity, urges and skills used.', 'Use it to help a client track feelings and which skills they used.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'Review the card each session and start with what went well. Look for skills used and what got in the way, without scolding. Keep columns simple so the client keeps doing it.', '[{"id": "f0", "type": "textarea", "label": "Strongest emotion today and its intensity:"}, {"id": "f1", "type": "textarea", "label": "Urges that came with it:"}, {"id": "f2", "type": "textarea", "label": "Skills I used:"}, {"id": "f3", "type": "textarea", "label": "What I will try tomorrow:"}]'::jsonb, array['diary card', 'emotion regulation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('please-skills-self-care-check', 'PLEASE Skills Self-Care Check', 'dbt'::resource_kind, 'A check on sleep, eating balance, activity, illness care and substance use that affect mood.', 'Use it to help a client reduce vulnerability to strong emotions through basic self-care.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through each letter and choose one area to improve this week. Keep the tone non-shaming and avoid prescriptive rules about food. Review the chosen area next session.', '[{"id": "f0", "type": "textarea", "label": "How I slept this week:"}, {"id": "f1", "type": "textarea", "label": "How I looked after my body:"}, {"id": "f2", "type": "textarea", "label": "What I did for physical health:"}, {"id": "f3", "type": "textarea", "label": "One area I will improve:"}]'::jsonb, array['PLEASE skills', 'self-care']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('stop-skill-practice-card', 'STOP Skill Practice Card', 'dbt'::resource_kind, 'A card for stopping, taking a step back, observing and proceeding mindfully.', 'Use it to help a client pause before acting on a strong urge.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice STOP with a mild, recent example, then a stronger one. Make a card the client keeps in a pocket. Encourage using it first on small moments so it is available when it counts.', '[{"id": "f0", "type": "textarea", "label": "A moment I needed to pause:"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I stepped back:"}, {"id": "f2", "type": "textarea", "label": "What I did next:"}, {"id": "f3", "type": "textarea", "label": "What I would do differently:"}]'::jsonb, array['STOP skill', 'distress tolerance']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('give-skill-for-keeping-relationships', 'GIVE Skill for Keeping Relationships', 'dbt'::resource_kind, 'A sheet practicing gentle, interested, validating and easy manner in conversations.', 'Use it to help a client keep a relationship strong while asking for something.', array['Adults', 'Teens']::text[], '25 minutes', 'Role-play a short conversation using each part of GIVE. The client notes which part is easiest. Combine with DEAR MAN later, and check how the other person responded.', '[{"id": "f0", "type": "textarea", "label": "A conversation coming up:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle and interested:"}, {"id": "f2", "type": "textarea", "label": "How I will validate:"}, {"id": "f3", "type": "textarea", "label": "What easy manner looks like for me:"}]'::jsonb, array['GIVE skill', 'interpersonal effectiveness']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('check-the-facts-emotion-worksheet', 'Check the Facts Emotion Worksheet', 'dbt'::resource_kind, 'A worksheet for checking whether an emotion fits the facts of a situation.', 'Use it to help a client see when feelings fit the facts and when they do not.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through the steps: name the emotion, the event, the interpretation and whether the facts fit. If they fit, problem solve; if not, act opposite. Keep it a real example.', '[{"id": "f0", "type": "textarea", "label": "The emotion and what set it off:"}, {"id": "f1", "type": "textarea", "label": "My interpretation:"}, {"id": "f2", "type": "textarea", "label": "The facts as best I know them:"}, {"id": "f3", "type": "textarea", "label": "Whether my feeling fits and what I will do:"}]'::jsonb, array['check the facts', 'emotion regulation']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('soft-start-up-practice-page', 'Soft Start-Up Practice Page', 'couples'::resource_kind, 'A page for turning a complaint into a gentle opening that invites listening.', 'Use it to help partners raise a concern without starting a fight.', array['Couples']::text[], '25 minutes', 'Each partner writes a complaint and rewrites it as an ''I feel, about, I need'' line. Read aloud to each other and swap. Notice how it lands and adjust wording.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my rewritten opening:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my rewritten opening:"}, {"id": "f2", "type": "textarea", "label": "What helped it land softly:"}, {"id": "f3", "type": "textarea", "label": "What we will try this week:"}]'::jsonb, array['Gottman', 'soft start-up', 'couples']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('sunday-sit-down-couple-agenda', 'Sunday Sit-Down Couple Agenda', 'couples'::resource_kind, 'An agenda for a weekly sit-down with appreciation, issues and plans.', 'Use it to help partners keep a regular, calm touchpoint.', array['Couples']::text[], '30 minutes', 'Set a fixed time, order and length. Start with appreciation, then one issue, then plans for the week. If it heats up, pause and resume later. Review how it went after two weeks.', '[{"id": "f0", "type": "textarea", "label": "What I appreciated this week:"}, {"id": "f1", "type": "textarea", "label": "One issue I would like to talk about:"}, {"id": "f2", "type": "textarea", "label": "What we agree to try:"}, {"id": "f3", "type": "textarea", "label": "When our next check-in is:"}]'::jsonb, array['check-in', 'couples', 'routine']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('love-map-question-cards', 'Love Map Question Cards', 'couples'::resource_kind, 'Cards with questions for learning each other''s inner world, such as hopes and worries.', 'Use it to help partners stay curious about each other.', array['Couples']::text[], '30 minutes', 'Partners take turns drawing a card and answering, then asking a follow-up. Rules: no fixing, no judgment, either may pass. Debrief on what surprised them.', '[{"id": "f0", "type": "textarea", "label": "A question I drew and answered:"}, {"id": "f1", "type": "textarea", "label": "Something new I learned about you:"}, {"id": "f2", "type": "textarea", "label": "What surprised me:"}, {"id": "f3", "type": "textarea", "label": "A question I want to ask next:"}]'::jsonb, array['Gottman', 'love maps', 'couples']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('shared-goals-and-dreams-map', 'Shared Goals and Dreams Map', 'couples'::resource_kind, 'A map where partners list shared goals, near and far, and one step for each.', 'Use it to help partners align on a future they both want.', array['Couples']::text[], '35 minutes', 'Each partner writes goals separately, then they combine and pick three. Plan a first step for each. Talk about differences without trying to decide who is right.', '[{"id": "f0", "type": "textarea", "label": "Goals I hope for us:"}, {"id": "f1", "type": "textarea", "label": "Goals we share:"}, {"id": "f2", "type": "textarea", "label": "One first step for each:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way:"}]'::jsonb, array['goals', 'couples', 'planning']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('after-work-unloading-talk-guide', 'After-Work Unloading Talk Guide', 'couples'::resource_kind, 'A guide for listening to each other''s outside stress without fixing.', 'Use it to help partners support each other after a hard day.', array['Couples']::text[], '25 minutes', 'One partner shares a stress outside the relationship while the other listens, asks questions and shows care. Then swap. Rules: no advice unless asked. Debrief on what felt supportive.', '[{"id": "f0", "type": "textarea", "label": "The stress I shared:"}, {"id": "f1", "type": "textarea", "label": "What my partner did that helped:"}, {"id": "f2", "type": "textarea", "label": "What I could do when you are stressed:"}, {"id": "f3", "type": "textarea", "label": "What we will try this week:"}]'::jsonb, array['stress', 'couples', 'listening']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('feelings-faces-collage', 'Feelings Faces Collage', 'kids'::resource_kind, 'A collage activity where a child cuts and pastes faces for different feelings.', 'Use it to help a child match feelings with names and faces.', array['Children']::text[], '25 minutes', 'The child finds faces in magazines and names the feeling for each. Ask when they last felt it. The parent joins and names a feeling of their own. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "A face for happy and what makes me happy:"}, {"id": "f1", "type": "textarea", "label": "A face for sad and what helps:"}, {"id": "f2", "type": "textarea", "label": "A face for mad and what helps:"}, {"id": "f3", "type": "textarea", "label": "The feeling I have most:"}]'::jsonb, array['feelings', 'children', 'collage']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('snow-globe-settling-jar-craft', 'Snow Globe Settling Jar Craft', 'kids'::resource_kind, 'A craft where a child makes a glitter jar and watches the glitter settle as they breathe.', 'Use it to help a child see calm as settling, not stopping.', array['Children']::text[], '25 minutes', 'Build the jar together, then shake it and breathe while the glitter settles. The parent uses the jar with the child at home. Explain that the glitter is thoughts and feelings settling.', '[{"id": "f0", "type": "textarea", "label": "What my jar looks like:"}, {"id": "f1", "type": "textarea", "label": "What I do while the glitter settles:"}, {"id": "f2", "type": "textarea", "label": "How I feel at the end:"}, {"id": "f3", "type": "textarea", "label": "When I will use my jar:"}]'::jsonb, array['calming', 'children', 'craft']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('kind-hands-helper-chart', 'Kind Hands Helper Chart', 'kids'::resource_kind, 'A chart where a child draws or records kind things they do with their hands each day.', 'Use it to help a child notice and repeat kind behavior.', array['Children']::text[], 'One week', 'The child traces a hand and fills in a kind act each day, with a sticker. The parent notices the act and says what it meant to someone. Keep it about effort and kindness, not perfection.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did today:"}, {"id": "f1", "type": "textarea", "label": "Who it helped:"}, {"id": "f2", "type": "textarea", "label": "How I felt:"}, {"id": "f3", "type": "textarea", "label": "A kind thing I want to do tomorrow:"}]'::jsonb, array['kindness', 'children', 'chart']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('strong-feelings-story-sequence-cards', 'Strong Feelings Story Sequence Cards', 'kids'::resource_kind, 'Picture cards a child puts in order to tell a story of a feeling building and settling.', 'Use it to help a child see a feeling as something that builds and passes.', array['Children']::text[], '25 minutes', 'The child draws four panels: trigger, big feeling, what helped and calm again. Ask them to tell the story. The parent practices the same story language in the day-to-day.', '[{"id": "f0", "type": "textarea", "label": "What happened first:"}, {"id": "f1", "type": "textarea", "label": "What the feeling did:"}, {"id": "f2", "type": "textarea", "label": "What helped:"}, {"id": "f3", "type": "textarea", "label": "How the story ends:"}]'::jsonb, array['feelings', 'children', 'storytelling']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('safe-grown-ups-and-helpers-map', 'Safe Grown-Ups and Helpers Map', 'kids'::resource_kind, 'A map where a child draws the people they can go to when something feels hard or wrong.', 'Use it to help a child name the people they can turn to.', array['Children']::text[], '25 minutes', 'The child draws people at home, school and the community they can tell. If a child discloses harm or abuse, follow your reporting duties and respond calmly. The parent keeps the map visible.', '[{"id": "f0", "type": "textarea", "label": "Grown-ups at home I can tell:"}, {"id": "f1", "type": "textarea", "label": "Helpers at school:"}, {"id": "f2", "type": "textarea", "label": "Other safe people:"}, {"id": "f3", "type": "textarea", "label": "What I can say when I need help:"}]'::jsonb, array['safety', 'children', 'support']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('feelings-charades-showdown', 'Feelings Charades Showdown', 'game'::resource_kind, 'A charades game where players act out feelings and situations for others to guess.', 'Use it to help players name emotions and read body language.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Players draw a card and act it out silently. Rules: no mocking, one guess per turn, anyone may pass. Debrief on what clues helped them guess and how emotions show in the body.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out:"}, {"id": "f1", "type": "textarea", "label": "The clue that gave it away:"}, {"id": "f2", "type": "textarea", "label": "A feeling I find hard to show:"}, {"id": "f3", "type": "textarea", "label": "What I learned about feelings:"}]'::jsonb, array['game', 'emotions', 'charades']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('skills-quiz-team-challenge', 'Skills Quiz Team Challenge', 'game'::resource_kind, 'A team trivia game about coping and communication skills the group has learned.', 'Use it to help a group review skills in a lively way.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make question cards from skills the group has covered. Teams take turns and share an example when they answer. Rules: help each other, no put-downs. Debrief on skills people want to practice.', '[{"id": "f0", "type": "textarea", "label": "A skill I remembered:"}, {"id": "f1", "type": "textarea", "label": "An example of using it:"}, {"id": "f2", "type": "textarea", "label": "A skill I want to practice:"}, {"id": "f3", "type": "textarea", "label": "What I will do this week:"}]'::jsonb, array['game', 'skills review', 'groups']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('strength-detective-hunt', 'Strength Detective Hunt', 'game'::resource_kind, 'A hunt where players find items or people that show a given strength and explain the link.', 'Use it to help players see strengths in themselves and others.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Give each player a strength list and let them find an item or recall a moment for each. They explain the link. Rules: no put-downs, anyone may pass. Debrief on which strength surprised them.', '[{"id": "f0", "type": "textarea", "label": "A strength I found:"}, {"id": "f1", "type": "textarea", "label": "The item or moment that shows it:"}, {"id": "f2", "type": "textarea", "label": "A strength I saw in someone else:"}, {"id": "f3", "type": "textarea", "label": "One I want to grow:"}]'::jsonb, array['game', 'strengths', 'groups']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('perspective-taking-role-swap-game', 'Perspective-Taking Role Swap Game', 'game'::resource_kind, 'A game where players retell a short conflict from another person''s point of view.', 'Use it to help players practice seeing a situation from another side.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Read a short scenario and have pairs retell it from the other character''s side. Rules: stay kind, no right or wrong answer, anyone may pass. Debrief on what was hard to imagine.', '[{"id": "f0", "type": "textarea", "label": "The scenario I picked:"}, {"id": "f1", "type": "textarea", "label": "How the other person might have felt:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about my own view:"}, {"id": "f3", "type": "textarea", "label": "A time I could try this at home:"}]'::jsonb, array['game', 'perspective-taking', 'empathy']::text[], '2026-11-01T15:00:00+00:00'::timestamptz),
  ('gratitude-pass-the-ball-circle', 'Gratitude Pass-the-Ball Circle', 'game'::resource_kind, 'A circle game where a ball passes and each holder names something they are thankful for.', 'Use it to help a group notice good things in a light, shared way.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'The holder says one thing they appreciate before passing the ball. Rules: no repeating, anyone may pass, and short answers are fine. Debrief on how it felt to listen and to share.', '[{"id": "f0", "type": "textarea", "label": "What I was thankful for:"}, {"id": "f1", "type": "textarea", "label": "Something another player said that I liked:"}, {"id": "f2", "type": "textarea", "label": "How I felt during the game:"}, {"id": "f3", "type": "textarea", "label": "One thing I will notice tomorrow:"}]'::jsonb, array['game', 'gratitude', 'groups']::text[], '2026-11-01T15:00:00+00:00'::timestamptz)
